import React, { useEffect, useState } from "react";

import Header from "./components/Header";
import DisputeForm from "./components/DisputeForm";
import Sidebar from "./components/Sidebar";
import Login from "./components/Login";

const API_URL = "http://localhost:5000/api";

function App() {

    const [student, setStudent] = useState(null);

    const [disputes, setDisputes] = useState([]);

    const [loading, setLoading] = useState(false);

    const [message, setMessage] = useState("");

    const [messageType, setMessageType] =
        useState("");

    useEffect(() => {

        const savedStudent =
            localStorage.getItem("student");

        if (savedStudent) {
            setStudent(
                JSON.parse(savedStudent)
            );
        }

    }, []);

    const showMessage = (text, type) => {

        setMessage(text);

        setMessageType(type);

        setTimeout(() => {
            setMessage("");
        }, 4000);
    };

    const handleLogin = (studentData) => {

        setStudent(studentData);

        localStorage.setItem(
            "student",
            JSON.stringify(studentData)
        );
    };

    const handleLogout = () => {

        localStorage.removeItem("student");

        setStudent(null);

        setDisputes([]);
    };

    const loadDisputes = async () => {

        if (!student) {
            return;
        }

        try {

            setLoading(true);

            const response = await fetch(
                `${API_URL}/disputes/${student.student_id}`
            );

            const data =
                await response.json();

            if (!response.ok) {

                throw new Error(
                    data.message ||
                    "Unable to load disputes."
                );
            }

            setDisputes(data);

        } catch (error) {

            console.error(error);

            showMessage(
                error.message,
                "error"
            );

        } finally {

            setLoading(false);

        }
    };

    useEffect(() => {

        if (student) {
            loadDisputes();
        }

    }, [student]);

    const handleCreate = async (formData) => {

        try {

            const response = await fetch(
                `${API_URL}/disputes`,
                {
                    method: "POST",

                    headers: {
                        "Content-Type":
                            "application/json"
                    },

                    body: JSON.stringify({

                        student_id:
                            student.student_id,

                        subject:
                            formData.subject,

                        grade_date:
                            formData.grade_date,

                        reason:
                            formData.reason

                    })
                }
            );

            const data =
                await response.json();

            if (!response.ok) {

                throw new Error(
                    data.message ||
                    "Unable to create dispute."
                );
            }

            setDisputes(previous => [
                data.dispute,
                ...previous
            ]);

            showMessage(
                "Dispute submitted successfully.",
                "success"
            );

        } catch (error) {

            showMessage(
                error.message,
                "error"
            );

            throw error;
        }
    };

    const handleResolve = async (id) => {

        try {

            const response = await fetch(
                `${API_URL}/disputes/${id}/resolve`,
                {
                    method: "PATCH"
                }
            );

            const data =
                await response.json();

            if (!response.ok) {

                throw new Error(
                    data.message ||
                    "Unable to resolve dispute."
                );
            }

            setDisputes(previous =>
                previous.map(dispute =>
                    dispute.id === id
                        ? data.dispute
                        : dispute
                )
            );

            showMessage(
                "Dispute marked as resolved.",
                "success"
            );

        } catch (error) {

            showMessage(
                error.message,
                "error"
            );
        }
    };

    if (!student) {

        return (
            <Login
                onLogin={handleLogin}
            />
        );
    }

    return (

        <div className="app">

            <Header
                student={student}
                onLogout={handleLogout}
            />

            <main className="container">

                <div className="page-heading">

                    <div>

                        <h2>
                            Academic Grade Disputes
                        </h2>

                        <p>
                            Submit and track your
                            grade-related concerns.
                        </p>

                    </div>

                    <div className="student-box">

                        <span>
                            Signed in as
                        </span>

                        <strong>
                            {student.student_id}
                        </strong>

                    </div>

                </div>

                {message && (

                    <div
                        className={`notification ${messageType}`}
                    >
                        {message}
                    </div>

                )}

                <div className="dashboard">

                    <DisputeForm
                        onCreated={handleCreate}
                    />

                    <Sidebar
                        disputes={disputes}
                        loading={loading}
                        onResolve={handleResolve}
                        onRefresh={loadDisputes}
                    />

                </div>

            </main>

        </div>
    );
}

export default App;
